/**
 * The library a first-time demo visitor sees. Shapes match what the real
 * backend stores (see generation.model.*Payload), so the same renderers
 * draw them unchanged.
 *
 * Every fact here was checked: algorithm steps and numbers come from running
 * the algorithms on these exact inputs, TLS from RFC 8446, anatomy against
 * standard references, and the vaccine storyboard (generated by Gemini in the
 * real app) was corrected where it was imprecise.
 */

function daysAgo(days) {
  return new Date(Date.now() - days * 86_400_000).toISOString();
}

const FOLDERS = [
  { id: "f-algorithms", name: "Algorithms", color: "teal", createdAt: daysAgo(30) },
  { id: "f-anatomy", name: "Anatomy", color: "coral", createdAt: daysAgo(24) },
  { id: "f-web", name: "Web & security", color: "sky", createdAt: daysAgo(18) },
  { id: "f-immunology", name: "Immunology", color: "green", createdAt: daysAgo(12) },
];

// Real images are referenced by an asset key (resolved in artwork.js), not a
// URL, so a redeploy that renames the files can't break a visitor's saved demo.
const GRAY_CREDIT = "Henry Gray, Anatomy of the Human Body (1918), public domain, via Wikimedia Commons";
