// ---- Storyboard helpers (same fields as AnimationPayload.Scene / VisualElement) ----
const box = (id, text, icon, enterAtSeconds, color, animation = "pop") =>
  ({ id, kind: "box", text, icon, enterAtSeconds, animation, color, fromId: "", toId: "" });
const arrow = (id, fromId, toId, text, enterAtSeconds, color = "coral") =>
  ({ id, kind: "arrow", text, icon: "", enterAtSeconds, animation: "draw", color, fromId, toId });
const scene = (order, title, narration, layout, transitionToNext, durationSeconds, visualElements) => ({
  id: `s${order}`,
  order,
  title,
  narration,
  durationSeconds,
  transitionToNext,
  layout,
  needsVisualAsset: false,
  visualPrompt: "",
  assetArtifactIds: [],
  visualElements,
});

// ---- Algorithms ----

const binarySearchFlow = {
  type: "diagram",
  version: 2,
  syntax: "mermaid",
  caption: "The loop behind binary search: compare with the middle, then keep only the half that can still hold the target.",
  source: `flowchart TD
  start["lo = 0, hi = n - 1"] --> check{"lo ≤ hi?"}
  check -->|"no"| miss["Not found"]
  check -->|"yes"| mid["mid = (lo + hi) / 2, rounded down"]
  mid --> cmp{"Compare a[mid] with the target"}
  cmp -->|"equal"| found["Found at index mid"]
  cmp -->|"a[mid] is smaller"| right["lo = mid + 1"]
  cmp -->|"a[mid] is bigger"| left["hi = mid - 1"]
  right --> check
  left --> check`,
};

