// ---- Web & security ----

// Message order checked against RFC 8446, section 2 (full handshake).
const tlsDiagram = {
  type: "diagram",
  version: 2,
  syntax: "mermaid",
  caption: "TLS 1.3 needs one round trip before encrypted data can flow; TLS 1.2 needed two.",
  source: `sequenceDiagram
  participant C as Browser
  participant S as Server
  C->>S: ClientHello (cipher suites, key share)
  S->>C: ServerHello (chosen cipher, key share)
  Note over C,S: Both derive the same handshake keys (ECDHE)
  S->>C: EncryptedExtensions and Certificate
  S->>C: CertificateVerify and Finished
  Note over C: Checks the certificate chain and the signature
  C->>S: Finished
  C->>S: HTTP request (encrypted)
  S->>C: HTTP response (encrypted)`,
};

const urlDiagram = {
  type: "diagram",
  version: 2,
  syntax: "mermaid",
  caption: "Opening https://example.com in a browser. With HTTP/3 the connection and TLS steps happen together over QUIC.",
  source: `flowchart TD
  url["You enter https://example.com"] --> dns["DNS lookup: browser, OS, then resolver"]
  dns -->|"IP address"| tcp["TCP connection (3-way handshake)"]
  tcp --> tls["TLS handshake: keys and certificate check"]
  tls --> req["HTTP request: GET /"]
  req --> res["Server responds with HTML"]
  res --> parse["Browser parses HTML"]
  parse -->|"finds CSS, JS, images"| more["More requests for those files"]
  parse --> render["Builds the DOM and CSSOM, lays out, paints"]
  more --> render`,
};

